(function(root){
 const modes={ongoing:'Ongoing',next:'Up next',progress:'In progress'};
 function rows(entries,mode){return entries.filter(x=>mode==='ongoing'?x.ongoing===true:mode==='next'?x.status==='Want to experience':x.status==='In progress');}
 if(typeof module==='object')module.exports={rows};if(typeof document==='undefined')return;
 const key='folio-library-shelves-v1';let prefs={enabled:true,collapsed:false,active:'next'};try{Object.assign(prefs,JSON.parse(localStorage.getItem(key)||'{}'));}catch{}
 function save(){try{localStorage.setItem(key,JSON.stringify(prefs));}catch{toast('Could not save shelf preferences.');}}
 const shelf=document.createElement('section');shelf.className='library-shelves';shelf.setAttribute('aria-label','Library shortcuts');document.querySelector('#library-page .heading').after(shelf);
 const manage=document.createElement('dialog');manage.className='shelf-manager';manage.setAttribute('aria-label','Manage library shelves');document.body.append(manage);
 function toggle(id){const entry=items.find(x=>x.id===id);if(!entry)return;const before=entry.ongoing;entry.ongoing=!before;if(!persist()){entry.ongoing=before;return;}render();syncButtons();}
 function art(entry){return entry.metadata?FolioArtwork.gallery(entry.metadata,entry).portrait:safeArt(entry.coverImage||entry.coverUrl);}
 function syncButtons(){for(const button of document.querySelectorAll('[data-ongoing-id]')){const x=items.find(x=>x.id===button.dataset.ongoingId);button.setAttribute('aria-pressed',String(!!x?.ongoing));button.innerHTML='<span aria-hidden="true">↻</span><span>Ongoing</span><span class="ongoing-state">'+(x?.ongoing?'On':'Off')+'</span>';button.title='Keep in your ongoing shelf, independently of status';}}
 function paint(){
  shelf.hidden=!prefs.enabled||['catalog','home','profile'].includes(view)||collectionSpace;if(shelf.hidden)return;if(!modes[prefs.active])prefs.active='next';
  const list=rows(items,prefs.active);
  shelf.innerHTML=`<div class="shelf-heading"><div class="shelf-tabs" role="group" aria-label="Choose library shelf">${Object.entries(modes).map(([id,label])=>`<button type="button" data-shelf="${id}" aria-pressed="${id===prefs.active}">${label} <small>${rows(items,id).length}</small></button>`).join('')}</div><button type="button" class="shelf-collapse" aria-expanded="${!prefs.collapsed}">${prefs.collapsed?'Show':'Collapse'}</button><button type="button" class="shelf-manage">Manage</button></div><div class="shelf-strip" ${prefs.collapsed?'hidden':''}>${list.map(x=>`<button type="button" class="shelf-title" data-shelf-title="${esc(x.id)}" aria-label="Open ${esc(x.title)}">${art(x)?`<img src="${esc(art(x))}" alt="" loading="lazy">`:'<span class="shelf-no-art" aria-hidden="true">▤</span>'}<span><strong>${esc(x.title)}</strong><small>${esc(x.type)}${x.year?' · '+esc(x.year):''}</small></span></button>`).join('')||`<p class="shelf-empty">${prefs.active==='ongoing'?'Keep games and other titles you return to here. Use Manage to choose them.':prefs.active==='next'?'Titles marked Up next will appear here.':'Titles marked In progress will appear here.'}</p>`}</div>`;
  shelf.querySelectorAll('[data-shelf]').forEach(b=>b.onclick=()=>{prefs.active=b.dataset.shelf;save();paint();});shelf.querySelectorAll('[data-shelf-title]').forEach(b=>b.onclick=()=>openOwnedDetail(b.dataset.shelfTitle));shelf.querySelector('.shelf-collapse').onclick=()=>{prefs.collapsed=!prefs.collapsed;save();paint();};shelf.querySelector('.shelf-manage').onclick=openManager;
 }
 function openManager(){manage.innerHTML=`<div class="shelf-manager-heading"><h2>Library shelves</h2><button type="button" aria-label="Close shelf settings">×</button></div><label class="shelf-check"><input type="checkbox" id="shelves-enabled" ${prefs.enabled?'checked':''}> Show library shelves</label><p>Ongoing is for titles you revisit, including live-service games. It stays independent of completion. Up next and In progress follow your library status.</p><label>Find ongoing titles<input type="search" class="shelf-find" placeholder="Search your library…"></label><div class="shelf-choices">${items.map(x=>`<label class="shelf-check" data-shelf-choice="${esc(x.title.toLocaleLowerCase())}"><input type="checkbox" value="${esc(x.id)}" ${x.ongoing?'checked':''}><span>${esc(x.title)} <small>${esc(x.type)}</small></span></label>`).join('')||'<p>Add a title to your library first.</p>'}</div>`;manage.querySelector('[aria-label="Close shelf settings"]').onclick=()=>manage.close();manage.querySelector('#shelves-enabled').onchange=e=>{prefs.enabled=e.target.checked;save();paint();};manage.querySelector('.shelf-find').oninput=e=>{for(const label of manage.querySelectorAll('[data-shelf-choice]'))label.hidden=!label.dataset.shelfChoice.includes(e.target.value.trim().toLocaleLowerCase());};manage.querySelectorAll('.shelf-choices input').forEach(input=>input.onchange=()=>toggle(input.value));manage.showModal();}
 const shortcut=document.createElement('button');shortcut.type='button';shortcut.className='secondary';shortcut.textContent='Shelves';shortcut.onclick=openManager;document.querySelector('.library-heading-actions').append(shortcut);
 const preference=document.createElement('section');preference.className='preferences-section';preference.innerHTML='<h3>Library shelves</h3><p class="muted">Choose ongoing titles or hide the shelf strip.</p><button type="button" class="secondary">Manage shelves</button>';document.querySelector('#preferences-dialog').append(preference);preference.querySelector('button').onclick=()=>{document.querySelector('#preferences-dialog').close();openManager();};
 const previousBind=FolioDetailPresentation.bind;FolioDetailPresentation.bind=function(container){previousBind(container);const hero=container.querySelector('.media-hero'),m=hero&&FolioMediaInfo.forElement(hero),entry=m?owned(fromMetadata(m)):items.find(x=>x.id===currentId);const actions=container.querySelector('.owned-actions,.live-detail-actions .media-action-row');const edit=container.querySelector('.library-summary-actions');if(actions&&edit){actions.append(...edit.children);edit.remove();}if(entry&&actions&&!actions.querySelector('[data-ongoing-id]')){const button=document.createElement('button');button.type='button';button.className='ongoing-control secondary';button.dataset.ongoingId=entry.id;actions.prepend(button);syncButtons();}};
 document.addEventListener('click',e=>{const button=e.target.closest('[data-ongoing-id]');if(button)toggle(button.dataset.ongoingId);});
 const previous=render;render=function(){previous();paint();};paint();root.FolioShelves={toggle,open:openManager};
})(globalThis);
